contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a depositAmount to first deposit into c on behalf of this contract, then attempt withdraw.
    // The function is payable so the caller can fund this test contract if needed.
    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract has funds to deposit
        require(address(this).balance >= depositAmount, "insufficient funds to deposit");

        // read balances before deposit
        uint256 beforeRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalanceBefore = address(c).balance;

        // perform deposit; if it reverts the test should still be meaningful, so capture revert flag
        bool depositReverted;
        c.addToBalance{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depositReverted = true;
        } else {
            depositReverted = false;
        }

        // read recorded balance and contract balance after deposit attempt
        uint256 afterRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalanceAfter = address(c).balance;

        // Now attempt withdraw; capture whether withdraw reverted
        bool withdrawReverted;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // read recorded balance and contract balance after withdraw attempt
        uint256 finalRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalanceFinal = address(c).balance;

        // General invariant we assert for all inputs:
        // If withdraw did not revert, then the recorded balance for this test contract must be zero
        // and C's Ether balance must have decreased by at least the recorded balance that existed
        // immediately before the withdraw (i.e., after deposit attempt). If withdraw reverted, no requirement.
        // Note: use values observable via public interface only.
        assert(withdrawReverted || (finalRecorded == 0 && cBalanceFinal + afterRecorded <= cBalanceAfter));
    }

    // receive callback so this test contract can accept Ether from C during withdraw
    receive() external payable {}
}

