pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint256 beforeRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint256 cBalanceBefore = address(c).balance;
        bool depositReverted;
        try c.addToBalance{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }
        uint256 afterRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint256 cBalanceAfter = address(c).balance;
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 finalRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { finalRecorded = __r; } catch { return; }
        uint256 cBalanceFinal = address(c).balance;
        assertTrue(withdrawReverted || (finalRecorded == 0 && cBalanceFinal + afterRecorded <= cBalanceAfter));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
